"""``INDEX.md`` generation — section 5 of ``AGENT_INSTRUCTIONS.md``.

Hand-maintained indexes go stale within three weeks, so this one is never
hand-edited: the pre-commit hook regenerates it and CI fails on a non-empty
diff. The table is derived entirely from ``experiments/*/manifest.yaml``.
"""

from __future__ import annotations

from utils.research_record.manifest import Manifest, ManifestError, load_manifest
from utils.research_record.paths import CURRENT_PATH, INDEX_PATH, experiment_dirs

_HEADER = """# Experiment Index

<!-- GENERATED BY `make index` — DO NOT EDIT.
     Source: docs/research/experiments/*/manifest.yaml
     Regenerate with: make index -->

Every experiment on record. Status is `planned` | `running` | `complete` |
`failed` | `superseded`; a failed or superseded entry is kept deliberately, so
that a dead end is walked into once rather than twice.

"""

_COLUMNS = (
    "ID",
    "Date",
    "Title",
    "Status",
    "Primary metric",
    "Claims",
    "Link",
)

_STATUS_ORDER = {"running": 0, "planned": 1, "complete": 2, "failed": 3, "superseded": 4}


def _primary_cell(manifest: Manifest) -> str:
    name = manifest.metrics.primary
    if not name:
        return "—"
    entry = manifest.metrics.values.get(name)
    if entry is None:
        return f"{name} (not recorded)"
    if entry.std is None:
        return f"{name} {entry.mean:.4f} (n={entry.n})"
    return f"{name} {entry.mean:.4f} ± {entry.std:.4f} (n={entry.n})"


def _row(manifest: Manifest, dirname: str) -> str:
    claims = ", ".join(manifest.supports_claims) if manifest.supports_claims else "—"
    date = manifest.date_completed or manifest.date_started
    status = manifest.status
    if manifest.superseded_by:
        status = f"{status} → {manifest.superseded_by}"
    cells = (
        f"`{manifest.id}`",
        str(date),
        manifest.title,
        status,
        _primary_cell(manifest),
        claims,
        f"[{manifest.slug}](experiments/{dirname}/)",
    )
    return "| " + " | ".join(cells) + " |"


def render_index() -> str:
    """Render the whole of ``INDEX.md`` as a string."""
    rows: list[tuple[tuple[int, str], str]] = []
    errors: list[str] = []

    for exp in experiment_dirs():
        try:
            manifest = load_manifest(exp / "manifest.yaml")
        except ManifestError as exc:
            errors.append(str(exc))
            continue
        sort_key = (_STATUS_ORDER.get(manifest.status, 9), manifest.id)
        rows.append((sort_key, _row(manifest, exp.name)))

    body = [_HEADER.rstrip("\n"), ""]
    body.append("| " + " | ".join(_COLUMNS) + " |")
    body.append("|" + "|".join("---" for _ in _COLUMNS) + "|")
    if rows:
        body.extend(row for _, row in sorted(rows, key=lambda item: item[0]))
    else:
        body.append("| — | — | *no experiments recorded yet* | — | — | — | — |")

    body.append("")
    body.append(f"**{len(rows)} experiment(s) on record.**")

    if errors:
        body.append("")
        body.append("## Unreadable manifests")
        body.append("")
        body.append(
            "These directories exist but their manifests do not parse. "
            "`make validate-research` reports the detail."
        )
        body.append("")
        body.extend(f"- {err}" for err in errors)

    body.append("")
    return "\n".join(body)


def write_index() -> bool:
    """Write ``INDEX.md``. Returns True if the file changed."""
    rendered = render_index()
    previous = INDEX_PATH.read_text() if INDEX_PATH.is_file() else None
    if previous == rendered:
        return False
    INDEX_PATH.write_text(rendered)
    return True


# ---------------------------------------------------------------------------
# CURRENT.md — the numbers that may be quoted today
# ---------------------------------------------------------------------------

_CURRENT_HEADER = """# Current figures

<!-- GENERATED BY `make index` — DO NOT EDIT.
     Source: docs/research/experiments/*/manifest.yaml
     Regenerate with: make index -->

**Read this before quoting any number from this repository.** It is derived
from the manifests, so it cannot drift from them: a headline is listed here
only while its experiment is the latest word, and every figure an experiment
has withdrawn is listed with the figure that replaced it. Prose anywhere in the
repository that quotes a withdrawn figure without its replacement is flagged by
`make check-docs`.

The claims ledger ([`CLAIMS.md`](CLAIMS.md)) says what each number *means*;
this file says which number is *current*.

"""


def _fmt(mean: float, std: float | None, n: int) -> str:
    if std is None:
        return f"{mean:.4f} (n={n})"
    return f"{mean:.4f} ± {std:.4f} (n={n})"


def render_current() -> str:
    """Render ``CURRENT.md``: withdrawn figures, superseded experiments, live headlines."""
    manifests: list[tuple[Manifest, str]] = []
    for exp in experiment_dirs():
        try:
            manifests.append((load_manifest(exp / "manifest.yaml"), exp.name))
        except ManifestError:
            continue
    by_id = {m.id: m for m, _ in manifests}

    body = [_CURRENT_HEADER.rstrip("\n"), ""]

    body.append("## Withdrawn figures — never quote these without the replacement")
    body.append("")
    withdrawn_rows = []
    for manifest, dirname in manifests:
        for name, cell in sorted(manifest.metrics.withdrawn.items()):
            withdrawn_rows.append(
                "| "
                + " | ".join(
                    (
                        f"`{manifest.id}`",
                        f"`{name}`",
                        _fmt(cell.mean, cell.std, cell.n),
                        str(cell.withdrawn_on),
                        cell.replaced_by,
                        cell.reason,
                    )
                )
                + " |"
            )
    if withdrawn_rows:
        body.append("| Experiment | Metric | Withdrawn value | Withdrawn on | Quote instead | Why |")
        body.append("|---|---|---|---|---|---|")
        body.extend(withdrawn_rows)
    else:
        body.append("*None recorded.*")
    body.append("")

    body.append("## Superseded experiments — cite the successor")
    body.append("")
    sup_rows = []
    for manifest, dirname in manifests:
        if manifest.superseded_by:
            succ = by_id.get(manifest.superseded_by)
            succ_title = succ.title if succ else "(not on record)"
            sup_rows.append(
                f"| `{manifest.id}` | {manifest.title} | `{manifest.superseded_by}` | {succ_title} |"
            )
    if sup_rows:
        body.append("| Experiment | Was | Superseded by | Which asks |")
        body.append("|---|---|---|---|")
        body.extend(sup_rows)
    else:
        body.append("*None recorded.*")
    body.append("")

    body.append("## Current headlines — one per experiment that is still the latest word")
    body.append("")
    body.append("| Experiment | Date | Headline metric | Value | Claims | Refines |")
    body.append("|---|---|---|---|---|---|")
    for manifest, dirname in manifests:
        if manifest.status != "complete" or manifest.superseded_by:
            continue
        name = manifest.metrics.primary or "—"
        cell = manifest.metrics.values.get(name) if manifest.metrics.primary else None
        value = _fmt(cell.mean, cell.std, cell.n) if cell else "—"
        claims = ", ".join(manifest.supports_claims) or "—"
        refines = f"`{manifest.supersedes}`" if manifest.supersedes else "—"
        date = manifest.date_completed or manifest.date_started
        body.append(
            f"| [`{manifest.id}`](experiments/{dirname}/) | {date} | `{name}` | {value} | {claims} | {refines} |"
        )
    body.append("")
    body.append(
        f"**{len(withdrawn_rows)} withdrawn figure(s), {len(sup_rows)} superseded experiment(s), "
        f"{sum(1 for m, _ in manifests if m.status == 'complete' and not m.superseded_by)} current headline(s).**"
    )
    body.append("")
    return "\n".join(body)


def write_current() -> bool:
    """Write ``CURRENT.md``. Returns True if the file changed."""
    rendered = render_current()
    previous = CURRENT_PATH.read_text() if CURRENT_PATH.is_file() else None
    if previous == rendered:
        return False
    CURRENT_PATH.write_text(rendered)
    return True
